create or replace function public.create_route_plan(p_name text, p_start_lat double precision, p_start_lng double precision, p_end_lat double precision, p_end_lng double precision, p_distance_miles numeric, p_estimated_minutes integer, p_stop_location_ids uuid[] default '{}'::uuid[]) returns uuid language plpgsql security definer set search_path to 'public','auth','extensions','pg_temp' as $function$
declare rid uuid; ids uuid[] := coalesce(p_stop_location_ids, '{}'::uuid[]); begin
  if auth.uid() is null then raise exception 'authentication required'; end if;
  if p_start_lat is null or p_start_lng is null or p_end_lat is null or p_end_lng is null then raise exception 'route coordinates are required'; end if;
  if p_start_lat not between -90 and 90 or p_end_lat not between -90 and 90 or p_start_lng not between -180 and 180 or p_end_lng not between -180 and 180 then raise exception 'route coordinates are invalid'; end if;
  if p_distance_miles is null or p_distance_miles < 0 or p_estimated_minutes is null or p_estimated_minutes < 0 then raise exception 'route metrics are invalid'; end if;
  if exists (select 1 from public.locations l where l.id = any(ids) and not l.is_active) then raise exception 'route contains inactive locations'; end if;
  if exists (select 1 from unnest(ids) x(id) left join public.locations l on l.id=x.id where l.id is null) then raise exception 'route contains unknown locations'; end if;
  insert into public.route_plans(user_id,name,status,start_lat,start_lng,end_lat,end_lng,distance_miles,estimated_minutes,stops_count) values(auth.uid(),coalesce(nullif(trim(p_name),''),'My route'),'active',p_start_lat,p_start_lng,p_end_lat,p_end_lng,p_distance_miles,p_estimated_minutes,cardinality(ids)) returning id into rid;
  if cardinality(ids) > 0 then insert into public.route_stops(route_id,location_id,stop_order) select rid,id,ord from unnest(ids) with ordinality as x(id,ord); end if;
  insert into public.route_events(route_id,user_id,event_type,points_awarded,metadata) values(rid,auth.uid(),'started',0,jsonb_build_object('source','create_route_plan','stop_location_ids',to_jsonb(ids)));
  return rid;
end $function$;

alter table public.location_address_backfills add column if not exists external_record_id uuid, add column if not exists osm_tags jsonb not null default '{}'::jsonb, add column if not exists raw_data jsonb not null default '{}'::jsonb;
create index if not exists location_address_backfills_external_record_idx on public.location_address_backfills(external_record_id);

create or replace function public.sync_external_location_address() returns trigger language plpgsql security definer set search_path='public','auth','extensions','pg_temp' as $function$
declare tags jsonb := coalesce(new.raw_data->'source_metadata'->'tags','{}'::jsonb); src record; display text; begin
  if new.location_id is null then return new; end if;
  select name,source_url into src from public.external_data_sources where id=new.source_id;
  display := nullif(new.raw_data->>'address','');
  if display is null then display := nullif(concat_ws(', ',nullif(concat_ws(' ',coalesce(new.raw_data->>'addr:housenumber',tags->>'addr:housenumber'),coalesce(new.raw_data->>'addr:street',tags->>'addr:street')),''),nullif(coalesce(new.raw_data->>'city',tags->>'addr:city'),''),nullif(coalesce(new.raw_data->>'state',tags->>'addr:state'),''),nullif(coalesce(new.raw_data->>'postal_code',tags->>'addr:postcode'),''),nullif(coalesce(new.raw_data->>'country',tags->>'addr:country'),'')), ''); end if;
  insert into public.location_address_backfills(location_id,provider,display_address,house_number,road,city,state,postal_code,country,latitude,longitude,fetched_at,source_url,metadata,external_record_id,osm_tags,raw_data) values(new.location_id,coalesce(src.name,'external'),display,coalesce(new.raw_data->>'addr:housenumber',tags->>'addr:housenumber'),coalesce(new.raw_data->>'addr:street',tags->>'addr:street'),coalesce(new.raw_data->>'city',tags->>'addr:city'),coalesce(new.raw_data->>'state',tags->>'addr:state'),coalesce(new.raw_data->>'postal_code',tags->>'addr:postcode'),coalesce(new.raw_data->>'country',tags->>'addr:country'),new.latitude,new.longitude,now(),src.source_url,jsonb_build_object('external_id',new.external_id,'record_type',new.record_type,'source_name',src.name,'source_updated_at',new.source_updated_at),new.id,tags,new.raw_data)
  on conflict(location_id) do update set provider=excluded.provider,display_address=coalesce(excluded.display_address,public.location_address_backfills.display_address),house_number=coalesce(excluded.house_number,public.location_address_backfills.house_number),road=coalesce(excluded.road,public.location_address_backfills.road),city=coalesce(excluded.city,public.location_address_backfills.city),state=coalesce(excluded.state,public.location_address_backfills.state),postal_code=coalesce(excluded.postal_code,public.location_address_backfills.postal_code),country=coalesce(excluded.country,public.location_address_backfills.country),latitude=coalesce(excluded.latitude,public.location_address_backfills.latitude),longitude=coalesce(excluded.longitude,public.location_address_backfills.longitude),fetched_at=excluded.fetched_at,source_url=coalesce(excluded.source_url,public.location_address_backfills.source_url),metadata=public.location_address_backfills.metadata || excluded.metadata,external_record_id=excluded.external_record_id,osm_tags=excluded.osm_tags,raw_data=excluded.raw_data;
  return new;
end $function$;

drop trigger if exists trg_sync_external_location_address on public.external_location_records;
create trigger trg_sync_external_location_address after insert or update of location_id,latitude,longitude,name,raw_data,source_updated_at,active on public.external_location_records for each row execute function public.sync_external_location_address();

with ranked as (select r.*,row_number() over(partition by r.location_id order by r.last_seen_at desc,r.id desc) as rn from public.external_location_records r where r.location_id is not null and r.active=true)
insert into public.location_address_backfills(location_id,provider,display_address,house_number,road,city,state,postal_code,country,latitude,longitude,fetched_at,source_url,metadata,external_record_id,osm_tags,raw_data)
select r.location_id,coalesce(s.name,'external'),nullif(r.raw_data->>'address',''),coalesce(r.raw_data->>'addr:housenumber',r.raw_data->'source_metadata'->'tags'->>'addr:housenumber'),coalesce(r.raw_data->>'addr:street',r.raw_data->'source_metadata'->'tags'->>'addr:street'),coalesce(r.raw_data->>'city',r.raw_data->'source_metadata'->'tags'->>'addr:city'),coalesce(r.raw_data->>'state',r.raw_data->'source_metadata'->'tags'->>'addr:state'),coalesce(r.raw_data->>'postal_code',r.raw_data->'source_metadata'->'tags'->>'addr:postcode'),coalesce(r.raw_data->>'country',r.raw_data->'source_metadata'->'tags'->>'addr:country'),r.latitude,r.longitude,now(),s.source_url,jsonb_build_object('external_id',r.external_id,'record_type',r.record_type,'source_name',s.name,'source_updated_at',r.source_updated_at),r.id,coalesce(r.raw_data->'source_metadata'->'tags','{}'::jsonb),r.raw_data from ranked r join public.external_data_sources s on s.id=r.source_id where r.rn=1
on conflict(location_id) do update set provider=excluded.provider,display_address=coalesce(excluded.display_address,public.location_address_backfills.display_address),house_number=coalesce(excluded.house_number,public.location_address_backfills.house_number),road=coalesce(excluded.road,public.location_address_backfills.road),city=coalesce(excluded.city,public.location_address_backfills.city),state=coalesce(excluded.state,public.location_address_backfills.state),postal_code=coalesce(excluded.postal_code,public.location_address_backfills.postal_code),country=coalesce(excluded.country,public.location_address_backfills.country),latitude=coalesce(excluded.latitude,public.location_address_backfills.latitude),longitude=coalesce(excluded.longitude,public.location_address_backfills.longitude),fetched_at=excluded.fetched_at,source_url=coalesce(excluded.source_url,public.location_address_backfills.source_url),metadata=public.location_address_backfills.metadata || excluded.metadata,external_record_id=excluded.external_record_id,osm_tags=excluded.osm_tags,raw_data=excluded.raw_data;
